namespace study {
template<class T>std::vector<T>read(std::ifstream&f,size_t n){std::vector<T>v(n);f.read((char*)v.data(),n*sizeof(T));if(!f)throw std::runtime_error("short fixture");return v;}
struct Fixture{std::vector<int>h,locals,nn,nl;std::vector<double>energy,time,potential,hr,hi,dx;std::vector<std::vector<double>>states;double volume,emax;};
Fixture fixture(const std::string&path){std::ifstream f(path,std::ios::binary);Fixture a;a.h=read<int>(f,12);auto s=read<double>(f,2);a.volume=s[0];a.emax=s[1];int n=a.h[0],pairs=n*a.h[1];a.energy=read<double>(f,a.h[2]);a.time=read<double>(f,a.h[3]);a.locals=read<int>(f,a.h[11]);a.nn=read<int>(f,n);a.nl=read<int>(f,pairs);a.potential=read<double>(f,n);a.hr=read<double>(f,pairs);a.hi=read<double>(f,pairs);a.dx=read<double>(f,pairs);for(int r=0;r<a.h[5];r++){a.states.push_back(read<double>(f,n));a.states.push_back(read<double>(f,n));}if(f.peek()!=EOF)throw std::runtime_error("trailing fixture");return a;}
template<class T>std::vector<double>colmajor(const std::vector<T>&row,int n,int maxn){std::vector<double>v(row.size());for(int k=0;k<maxn;k++)for(int i=0;i<n;i++)v[k*n+i]=row[i*maxn+k];return v;}
void H_inputs(Model&m,const Fixture&a){auto&s=lsqtstudy::state();if(!s.capture)return;int h[]={m.number_of_atoms,m.max_neighbor,m.number_of_energy_points,m.number_of_steps_correlation,m.number_of_moments,m.number_of_random_vectors,int(m.calculate_vac0),int(m.calculate_vac),int(m.calculate_msd),int(m.calculate_spin),int(m.calculate_ldos),m.number_of_local_orbitals};for(int i=0;i<12;i++){if(h[i]!=a.h[i])throw std::runtime_error("native model metadata differs from fixture");}if(m.volume!=a.volume||m.energy_max!=a.emax)throw std::runtime_error("model scalar differs");s.prefix.push_back(s.case_id);for(int x:h)s.prefix.push_back(x);s.prefix.insert(s.prefix.end(),{m.volume,m.energy_max});s.prefix.insert(s.prefix.end(),m.energy,m.energy+m.number_of_energy_points);s.prefix.insert(s.prefix.end(),m.time_step,m.time_step+m.number_of_steps_correlation);for(int x:m.local_orbitals)s.prefix.push_back(x);
 int n=h[0],maxn=h[1];std::map<int,std::vector<double>>expected={{0,std::vector<double>(a.nn.begin(),a.nn.end())},{1,colmajor(a.nl,n,maxn)},{2,a.potential},{3,colmajor(a.hr,n,maxn)},{4,colmajor(a.hi,n,maxn)},{5,colmajor(a.dx,n,maxn)}};std::map<int,void*>ptr;for(const auto&pair:s.live)ptr[pair.second.id]=pair.first;for(int id=0;id<6;id++){auto values=lsqtstudy::snapshot(ptr.at(id),"input_Hamiltonian");if(values!=expected.at(id))throw std::runtime_error("native actualGPU Hamiltonian differs from source fixture");s.prefix.insert(s.prefix.end(),values.begin(),values.end());}}
void state_inputs(Vector&v,int n,const std::vector<double>&re,const std::vector<double>&im){auto&s=lsqtstudy::state();if(!s.capture)return;lsqtstudy::initial_state(n,v.real_part,v.imag_part);std::vector<double>a(n),b(n);lsqtstudy::check(cudaMemcpy(a.data(),v.real_part,n*8,cudaMemcpyDeviceToHost));lsqtstudy::check(cudaMemcpy(b.data(),v.imag_part,n*8,cudaMemcpyDeviceToHost));if(a!=re||b!=im)throw std::runtime_error("actualnative sourceinitializedGPUstate differs from sourcefixture");}
void timed(int code,const std::function<void()>&function){lsqtstudy::roi_begin(code);function();lsqtstudy::roi_end();}
void run_case(const std::string&dir,const Fixture&a){auto&s=lsqtstudy::state();for(const char*name:{"dos.out","vac0.out","vac.out","msd.out","S.out","ldos.out"})std::filesystem::remove(name);Model m(dir);Hamiltonian H(m);H_inputs(m,a);Vector initial(m.number_of_atoms);
 for(int r=0;r<m.number_of_random_vectors;r++){s.r=r;s.kind=0;s.step=0;s.orbital=-1;m.initialize_state(initial,-1);state_inputs(initial,m.number_of_atoms,a.states[2*r],a.states[2*r+1]);timed(1,[&]{find_dos(m,H,initial,0);});if(m.calculate_vac0)timed(2,[&]{find_vac0(m,H,initial);});if(m.calculate_vac)timed(3,[&]{find_vac(m,H,initial);});if(m.calculate_msd)timed(4,[&]{find_msd(m,H,initial);});if(m.calculate_spin)timed(5,[&]{find_spin_polarization(m,H,initial);});}
 if(m.calculate_ldos){s.r=-1;timed(6,[&]{for(int orbital:m.local_orbitals){s.orbital=orbital;s.step=0;m.initialize_state(initial,orbital);std::vector<double>re(m.number_of_atoms,0),im(m.number_of_atoms,0);re[orbital]=sqrt(double(m.number_of_atoms));state_inputs(initial,m.number_of_atoms,re,im);find_dos(m,H,initial,1);}});}
}
}
int main(int argc,char**argv){try{if(argc<4||argc>5)throw std::runtime_error("case root, fixture root, persistent evidence folder, optional pilot");bool pilot=argc==5&&std::string(argv[4])=="pilot";std::string cases=argv[1],fixtures=argv[2],folder=argv[3];std::filesystem::create_directories(folder);std::vector<std::string>names={"diffusive","localized","small_lattice","general_tail","spin_pairs"};std::vector<study::Fixture>data;for(auto name:names)data.push_back(study::fixture(fixtures+"/"+name+"_fixture.bin"));auto&s=lsqtstudy::state();
 for(int trial=0;trial<=(pilot?1:5);trial++){s.capture=trial>0;s.prefix.clear();s.output.clear();s.correct=true;s.seconds=0;auto start=std::chrono::steady_clock::now();for(int c=0;c<int(names.size());c++){lsqtstudy::begin_case(folder,"cuda",trial,c);study::run_case(cases+"/"+names[c],data[c]);lsqtstudy::end_case();}double wall=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();if(!trial)continue;size_t prefix=s.prefix.size();s.prefix.insert(s.prefix.end(),s.output.begin(),s.output.end());std::string path="trial"+std::to_string(trial)+".bin";std::ofstream out(path,std::ios::binary);lsqtstudy::bytes(out,s.prefix.data(),s.prefix.size()*8);out.close();printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":null,\"max_rel_error\":null,\"input_prefix_values\":%zu,\"instrumented_driver_wall_seconds\":%.17g,\"timing_region\":\"sum_source_run_DOS_VAC0_VAC_MSD_spin_LDOS_functions_hostmath_alloc_IO_lifetimes_instrumented\",\"jit_excluded\":true,\"internal_repeats\":1,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,s.seconds,s.correct?"true":"false",s.prefix.size(),prefix,wall,path.c_str(),s.prefix.size());fflush(stdout);if(!s.correct)return 1;}return 0;
}catch(const std::exception&e){fprintf(stderr,"%s\n",e.what());return 1;}}
